@startuml

class User {
  + UserID : int
  + Name : string
  + Address : string
  + BirthDate : date
}

class BusinessOwner {
  + LinkedInAccount : string
}

class PizzaRestaurant {
  + ZipCode : string
  + Address : string
  + PhoneNumber : string
  + Website : string
  + OpeningHours : string
}

class Pizza {
  + Name : string
  + CrustStructure : string
  + Price : double
}

class Order {
  + OrderID : int
  + DateAndTime : datetime
  + LatestDeliveryTime : datetime
  + NumberOfPeople : int
}

class EntertainmentOrder {
  + EntertainmentType : string
  + Duration : time
}

class Entertainer {
  + StageName : string
  + Bio : string
  + PricePer30Minutes : double
}

class Availability {
  + Day : string
}

PizzaRestaurant "1" -- "*" Pizza
BusinessOwner --|> User
User "1..*" -- "0..*" PizzaRestaurant : owns
HungryCustomer --|> User
Entertainer --|> User
HungryCustomer "0..*" -- "1..*" Order : makes
Order "1" -- "0..1" EntertainmentOrder
Entertainer "1" -- "1" EntertainmentOrder : fulfills
PizzaRestaurant "1" -- "*" Entertainer : has
Entertainer "1" -- "*" Availability

@enduml

